insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) select id,kind,title,course_id,payload,published,restaurant_id,department from jsonb_populate_record(null::public.academy_content,$doc${"id":"rvb-admin-internship-test-2","kind":"test","title":"РВБ · Стажировка · Команда и обязанности","course_id":"guru-42932","published":true,"restaurant_id":"minsk","department":"Зал","payload":{"id":"rvb-admin-internship-test-2","title":"РВБ · Стажировка · Команда и обязанности","priority":"start","audiencePositions":["Администратор"],"timeLimitSeconds":0,"passCount":9,"questions":[{"id":"rvb-admin-internship-test-2-q1","text":"Что входит в обязанности гардеробщика?","type":"single","options":["Проверка броней и рассадка гостей","Приготовление напитков","Приём верхней одежды гостей, выдача номерков/браслетов, поддержание порядка","Контроль времени прихода персонала"]},{"id":"rvb-admin-internship-test-2-q2","text":"Что должна знать хостес для работы с гостями на входе?","type":"single","options":["Схему зала, условия входа, актуальные акции, работу с предоплатами","Только схему зала","Только работу с предоплатами","Только актуальные акции"]},{"id":"rvb-admin-internship-test-2-q3","text":"Какова основная задача официанта?","type":"single","options":["Проверять бронирования","Готовить напитки","Встречать гостей, принимать заказы, подавать блюда, убирать посуду, работать с отзывами, продавать","Контролировать чистоту в туалетах"]},{"id":"rvb-admin-internship-test-2-q4","text":"Как официант взаимодействует с баром?","type":"single","options":["Официант не взаимодействует с баром","Бармен сам подаёт напитки гостям","Передаёт заказ в iiko, бармен готовит, официант забирает и подаёт","Самостоятельно готовит напитки"]},{"id":"rvb-admin-internship-test-2-q5","text":"Что входит в обязанности бармена?","type":"single","options":["Базовые процессы барной станции, взаимодействие с официантами, контроль чистоты и маркировки","Работа с таблицей 