do $$ begin if exists(select 1 from public.academy_content c left join academy_private.test_keys k on k.test_id=c.id where c.id like 'rvb-admin-internship-test-%' and (k.test_id is null or exists(select 1 from jsonb_array_elements(c.payload->'questions') q where jsonb_typeof(k.keys->(q->>'id')) is distinct from 'array'))) then raise exception 'Missing RVB administrator answer key';end if;end $$;
commit;
select id,jsonb_array_length(payload->'questions') questions from public.academy_content where id like 'rvb-admin-internship-test-%' order by id;
